1	//! FFI 公开 API 层。
2	//!
3	//! 对应 sqlite3.h 中的 C 函数。每个函数必须是 `#[no_mangle] pub unsafe extern "C"`,
4	//! 签名与官方保持 byte-for-byte 一致(指针宽度、整数宽度、调用约定)。
5	//!
6	//! 当前 P0 阶段只实现 4 个最小可验证函数:
7	//!  - `sqlite3_libversion`
8	//!  - `sqlite3_libversion_number`
9	//!  - `sqlite3_open`            (桩 — 分配 handle,返回 OK)
10	//!  - `sqlite3_close`           (桩 — 释放 handle,返回 OK)
11	//! 后续子任务会把它们替换为真实实现。
12	
13	use std::ffi::{c_char, c_int, c_void, CStr};
14	
15	use crate::error::SqliteError;
16	use crate::handle::SqliteDb;
17	
18	/// 返回 SQLite 版本字符串。生命周期 = 进程,不需要 free。
19	///
20	/// C 契约:`const char *sqlite3_libversion(void);`
21	#[no_mangle]
22	pub unsafe extern "C" fn sqlite3_libversion() -> *const c_char {
23	    // 'static 字符串嵌入二进制
24	    SQLITE_VERSION_STR.as_ptr() as *const c_char
25	}
26	
27	/// 返回 SQLite 版本号(形如 3054000 = 3.54.0)。
28	#[no_mangle]
29	pub unsafe extern "C" fn sqlite3_libversion_number() -> c_int {
30	    crate::SQLITE_VERSION_NUMBER
31	}
32	
33	/// 打开/创建数据库。P0 桩:接受任意 filename,分配一个 handle 写回。
34	///
35	/// C 契约:`int sqlite3_open(const char *filename, sqlite3 **ppDb);`
36	///
37	/// # Safety
38	/// - `filename` 必须是 NUL 结尾的 UTF-8 字符串(可为 null)
39	/// - `pp_db` 必须是非空指针
40	#[no_mangle]
41	pub unsafe extern "C" fn sqlite3_open(filename: *const c_char, pp_db: *mut *mut SqliteDb) -> c_int {
42	    if !filename.is_null() {
43	        // SAFETY: 调用方保证 filename 是 NUL 结尾的 UTF-8 字符串。
44	        if unsafe { CStr::from_ptr(filename) }.to_str().is_err() {
45	            return SqliteError::ERROR.code();
46	        }
47	    }
48	    if pp_db.is_null() {
49	        return SqliteError::MISUSE.code();
50	    }
51	    let db = SqliteDb::new();
52	    // SAFETY: pp_db 已校验非 null,写一个有效指针。
53	    unsafe { *pp_db = Box::into_raw(db) };
54	    SqliteError::OK.code()
55	}
56	
57	/// 关闭数据库,释放 handle。P0 桩。
58	///
59	/// C 契约:`int sqlite3_close(sqlite3 *db);`
60	///
61	/// # Safety
62	/// `db` 必须是由 `sqlite3_open` 返回的指针,且不能被 close 两次。
63	#[no_mangle]
64	pub unsafe extern "C" fn sqlite3_close(db: *mut SqliteDb) -> c_int {
65	    if db.is_null() {
66	        return SqliteError::OK.code();
67	    }
68	    // SAFETY: db 由 sqlite3_open 通过 Box::into_raw 产生,这里取回所有权。
69	    let _ = unsafe { Box::from_raw(db) };
70	    SqliteError::OK.code()
71	}
72	
73	/// 返回最近一次错误的 UTF-8 字符串。P0 桩:返回占位。
74	#[no_mangle]
75	pub unsafe extern "C" fn sqlite3_errmsg(db: *mut SqliteDb) -> *const c_char {
76	    let _ = db;
77	    ERRSG_NOT_IMPL.as_ptr() as *const c_char
78	}
79	
